def test_observed_records(pairs):
    seen=[]
    def handler(request):
        seen.append(request)
        if len(seen)==1:
            headers=[('Set-Cookie',name+'='+value+'; Path=/; Expires=Wed, 09 Jun 2038 10:18:14 GMT') for name,value in pairs]
            return httpx.Response(200,headers=headers,text='stored')
        return httpx.Response(200,json={'cookie':request.headers.get('cookie','')})
    with httpx.Client(transport=httpx.MockTransport(handler),trust_env=False) as client:
        first=client.get('http://case.invalid/set')
        assert dict(first.cookies)==dict(pairs) and dict(client.cookies)==dict(pairs)
        second=client.get('http://case.invalid/check')
    jar=SimpleCookie(); jar.load(second.json()['cookie'])
    assert {name:m.value for name,m in jar.items()}==dict(pairs)

@property
def reason_phrase(self) -> str:
    try:
        reason_phrase: bytes = self.extensions["reason_phrase"]
    except KeyError:
        return codes.get_reason_phrase(self.status_code)
    else:
        return reason_phrase.decode("ascii", errors="ignore")

@classmethod
def get_reason_phrase(cls, value: int) -> str:
    try:
        return codes(value).phrase  # type: ignore
    except ValueError:
        return ""

@property
def cookies(self) -> Cookies:
    """
    Cookie values to include when sending requests.
    """
    return self._cookies

def __bool__(self) -> bool:
    for _ in self.jar:
        return True
    return False

@property
def cookies(self) -> Cookies:
    if not hasattr(self, "_cookies"):
        self._cookies = Cookies()
        self._cookies.extract_cookies(self)
    return self._cookies

@property
def request(self) -> Request:
    """
    Returns the request instance associated to the current response.
    """
    if self._request is None:
        raise RuntimeError(
            "The request instance has not been set on this response."
        )
    return self._request

@property
def http_version(self) -> str:
    try:
        http_version: bytes = self.extensions["http_version"]
    except KeyError:
        return "HTTP/1.1"
    else:
        return http_version.decode("ascii", errors="ignore")

def __repr__(self) -> str:
    cookies_repr = ", ".join(
        [
            f"<Cookie {cookie.name}={cookie.value} for {cookie.domain} />"
            for cookie in self.jar
        ]
    )

    return f"<Cookies[{cookies_repr}]>"

@property
def headers(self) -> Headers:
    """
    HTTP headers to include when sending requests.
    """
    return self._headers

def update(self, headers: HeaderTypes | None = None) -> None:  # type: ignore
    headers = Headers(headers)
    for key in headers.keys():
        if key in self:
            self.pop(key)
    self._list.extend(headers._list)

@headers.setter
def headers(self, headers: HeaderTypes) -> None:
    client_headers = Headers(
        {
            b"Accept": b"*[EXTERNAL]/*",
            b"Accept-Encoding": ACCEPT_ENCODING.encode("ascii"),
            b"Connection": b"keep-alive",
            b"User-Agent": USER_AGENT.encode("ascii"),
        }
    )
    client_headers.update(headers)
    self._headers = client_headers

def _transport_for_url(self, url: URL) -> BaseTransport:
    """
    Returns the transport instance that should be used for a given URL.
    This will either be the standard connection pool, or a proxy.
    """
    for pattern, transport in self._mounts.items():
        if pattern.matches(url):
            return self._transport if transport is None else transport

    return self._transport

