@pytest.mark.parametrize('kind',['json','form','raw'])
def test_observed_records(kind):
    captured=[]
    def app(environ,start_response):
        captured.append(environ)
        length=environ.get('CONTENT_LENGTH','0')
        body=environ['wsgi.input'].read(int(length))
        payload={'length':length,'type':environ.get('CONTENT_TYPE'),'body':body.decode(),'mode':environ.get('HTTP_X_MODE')}
        start_response('200 OK',[('Content-Type','application/json')]); return [json.dumps(payload).encode()]
    options={'json':{'x':2}} if kind=='json' else {'data':{'x':'two'}} if kind=='form' else {'content':b'raw-body','headers':{'content-type':'application/octet-stream','x-mode':'keep'}}
    options.setdefault('headers',{})['x-mode']='keep'
    with httpx.Client(transport=httpx.WSGITransport(app),trust_env=False) as client:
        request=client.build_request('POST','http://case.invalid/upload',**options)
        expected_body=request.read().decode()
        result=client.send(request).json()
    assert result=={'length':str(len(expected_body.encode())),'type':request.headers['content-type'],'body':expected_body,'mode':'keep'}
    assert 'HTTP_CONTENT_LENGTH' not in captured[0] and 'HTTP_CONTENT_TYPE' not in captured[0]

def _prepare(self, default_headers: dict[str, str]) -> None:
    for key, value in default_headers.items():
        # Ignore Transfer-Encoding if the Content-Length has been set explicitly.
        if key.lower() == "transfer-encoding" and "Content-Length" in self.headers:
            continue
        self.headers.setdefault(key, value)

    auto_headers: list[tuple[bytes, bytes]] = []

    has_host = "Host" in self.headers
    has_content_length = (
        "Content-Length" in self.headers or "Transfer-Encoding" in self.headers
    )

    if not has_host and self.url.host:
        auto_headers.append((b"Host", self.url.netloc))
    if not has_content_length and self.method in ("POST", "PUT", "PATCH"):
        auto_headers.append((b"Content-Length", b"0"))

    self.headers = Headers(auto_headers + self.headers.raw)

def get(self, key: str, default: typing.Any = None) -> typing.Any:
    """
    Return a header value. If multiple occurrences of the header occur
    then concatenate them together with commas.
    """
    try:
        return self[key]
    except KeyError:
        return default

def __contains__(self, key: typing.Any) -> bool:
    header_key = key.lower().encode(self.encoding)
    return header_key in [key for _, key, _ in self._list]

@property
def raw(self) -> list[tuple[bytes, bytes]]:
    """
    Returns a list of the raw header items, as byte pairs.
    """
    return [(raw_key, value) for raw_key, _, value in self._list]

@property
def content(self) -> bytes:
    if not hasattr(self, "_content"):
        raise ResponseNotRead()
    return self._content

def encode_json(json: Any) -> tuple[dict[str, str], ByteStream]:
    body = json_dumps(
        json, ensure_ascii=False, separators=(",", ":"), allow_nan=False
    ).encode("utf-8")
    content_length = str(len(body))
    content_type = "application/json"
    headers = {"Content-Length": content_length, "Content-Type": content_type}
    return headers, ByteStream(body)

def encode_urlencoded_data(
    data: RequestData,
) -> tuple[dict[str, str], ByteStream]:
    plain_data = []
    for key, value in data.items():
        if isinstance(value, (list, tuple)):
            plain_data.extend([(key, primitive_value_to_str(item)) for item in value])
        else:
            plain_data.append((key, primitive_value_to_str(value)))
    body = urlencode(plain_data, doseq=True).encode("utf-8")
    content_length = str(len(body))
    content_type = "application/x-www-form-urlencoded"
    headers = {"Content-Length": content_length, "Content-Type": content_type}
    return headers, ByteStream(body)

@property
def content(self) -> bytes:
    if not hasattr(self, "_content"):
        raise RequestNotRead()
    return self._content

def get_multipart_boundary_from_content_type(
    content_type: bytes | None,
) -> bytes | None:
    if not content_type or not content_type.startswith(b"multipart/form-data"):
        return None
    # parse boundary according to
    # https://www.rfc-editor.org/rfc/rfc2046#section-5.1.1
    if b";" in content_type:
        for section in content_type.split(b";"):
            if section.strip().lower().startswith(b"boundary="):
                return section.strip()[len(b"boundary=") :].strip(b'"')
    return None

def encode_content(
    content: str | bytes | Iterable[bytes] | AsyncIterable[bytes],
) -> tuple[dict[str, str], SyncByteStream | AsyncByteStream]:
    if isinstance(content, (bytes, str)):
        body = content.encode("utf-8") if isinstance(content, str) else content
        content_length = len(body)
        headers = {"Content-Length": str(content_length)} if body else {}
        return headers, ByteStream(body)

    elif isinstance(content, Iterable) and not isinstance(content, dict):
        # `not isinstance(content, dict)` is a bit oddly specific, but it
        # catches a case that's easy for users to make in error, and would
        # otherwise pass through here, like any other bytes-iterable,
        # because `dict` happens to be iterable. See issue #2491.
        content_length_or_none = peek_filelike_length(content)

        if content_length_or_none is None:
            headers = {"Transfer-Encoding": "chunked"}
        else:
            headers = {"Content-Length": str(content_length_or_none)}
        return headers, IteratorByteStream(content)  # type: ignore

    elif isinstance(content, AsyncIterable):
        headers = {"Transfer-Encoding": "chunked"}
        return headers, AsyncIteratorByteStream(content)

    raise TypeError(f"Unexpected type for 'content', {type(content)!r}")

@property
def headers(self) -> Headers:
    """
    HTTP headers to include when sending requests.
    """
    return self._headers

def update(self, headers: HeaderTypes | None = None) -> None:  # type: ignore
    headers = Headers(headers)
    for key in headers.keys():
        if key in self:
            self.pop(key)
    self._list.extend(headers._list)

@headers.setter
def headers(self, headers: HeaderTypes) -> None:
    client_headers = Headers(
        {
            b"Accept": b"*[EXTERNAL]/*",
            b"Accept-Encoding": ACCEPT_ENCODING.encode("ascii"),
            b"Connection": b"keep-alive",
            b"User-Agent": USER_AGENT.encode("ascii"),
        }
    )
    client_headers.update(headers)
    self._headers = client_headers

@request.setter
def request(self, value: Request) -> None:
    self._request = value

